package com.smartmess.web;

import com.smartmess.model.MenuItem;
import com.smartmess.service.IMessService;

import javax.servlet.ServletException;
import javax.servlet.http.HttpServlet;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import java.io.IOException;
import java.io.PrintWriter;
import java.util.List;

/**
 * Demonstrates Java Web Servlets:
 * Renders the HTML5 Web Portal directly from a pure Java HttpServlet.
 * Eliminates JavaScript frameworks by serving pure HTML & CSS generated by Java.
 */
public class WebPortalServlet extends HttpServlet {

    private final IMessService messService;

    public WebPortalServlet(IMessService messService) {
        this.messService = messService;
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp) throws ServletException, IOException {
        resp.setContentType("text/html");
        resp.setCharacterEncoding("UTF-8");

        List<MenuItem> items = messService.getCatalog().getAllItems();

        try (PrintWriter out = resp.getWriter()) {
            out.println("<!DOCTYPE html>");
            out.println("<html lang='en'>");
            out.println("<head>");
            out.println("  <meta charset='UTF-8'>");
            out.println("  <meta name='viewport' content='width=device-width, initial-scale=1.0'>");
            out.println("  <title>SmartMess - Campus Web Portal (Java Servlets)</title>");
            out.println("  <style>");
            out.println("    body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; background: #0f172a; color: #f8fafc; margin: 0; padding: 0; }");
            out.println("    header { background: #1e293b; padding: 16px 24px; border-bottom: 1px solid #334155; display: flex; align-items: center; justify-content: space-between; }");
            out.println("    .logo { color: #38bdf8; font-size: 22px; font-weight: bold; }");
            out.println("    .badge { background: #334155; padding: 6px 12px; border-radius: 6px; font-size: 13px; color: #cbd5e1; }");
            out.println("    .badge strong { color: #10b981; }");
            out.println("    .container { max-width: 1100px; margin: 24px auto; padding: 0 16px; }");
            out.println("    .card { background: #1e293b; border: 1px solid #334155; border-radius: 8px; padding: 20px; margin-bottom: 24px; }");
            out.println("    h2 { color: #38bdf8; margin-top: 0; font-size: 18px; border-bottom: 1px solid #334155; padding-bottom: 8px; }");
            out.println("    table { width: 100%; border-collapse: collapse; margin-top: 12px; }");
            out.println("    th, td { padding: 10px 14px; text-align: left; border-bottom: 1px solid #334155; }");
            out.println("    th { background: #0f172a; color: #94a3b8; font-weight: 600; }");
            out.println("    tr:hover { background: #26334d; }");
            out.println("    .btn { background: #10b981; color: white; border: none; padding: 6px 12px; border-radius: 4px; font-weight: bold; cursor: pointer; text-decoration: none; display: inline-block; }");
            out.println("    .btn-blue { background: #3b82f6; }");
            out.println("    .tag { background: #065f46; color: #34d399; padding: 2px 8px; border-radius: 12px; font-size: 11px; font-weight: bold; }");
            out.println("    .footer { text-align: center; color: #64748b; font-size: 12px; margin-top: 32px; padding: 16px; }");
            out.println("  </style>");
            out.println("</head>");
            out.println("<body>");

            // Header
            out.println("  <header>");
            out.println("    <div class='logo'>🍱 SMARTMESS WEB PORTAL</div>");
            out.println("    <div class='badge'>👤 Rohit Kundu (ID: 22) | Room: Block B-304 | Balance: <strong>1,250 Credits</strong></div>");
            out.println("  </header>");

            out.println("  <div class='container'>");

            // Tech Banner
            out.println("    <div class='card' style='background: #020617; border-color: #38bdf8;'>");
            out.println("      <h2 style='color: #38bdf8; border-color: #1e293b;'>⚡ 100% Pure Java Full-Stack Web Architecture</h2>");
            out.println("      <p style='color: #cbd5e1; line-height: 1.6; margin: 0;'>");
            out.println("        This web page is rendered dynamically in pure Java by <strong><code>WebPortalServlet</code></strong> (extending <code>javax.servlet.http.HttpServlet</code>).<br>");
            out.println("        All database queries use <strong>Pure JDBC (<code>java.sql.*</code>)</strong> against PostgreSQL, with atomic ACID transactions and zero JavaScript frameworks.");
            out.println("      </p>");
            out.println("    </div>");

            // Menu Section
            out.println("    <div class='card'>");
            out.println("      <h2>🍽️ Live Cafeteria Menu (Generated by Java Servlet)</h2>");
            out.println("      <table>");
            out.println("        <thead>");
            out.println("          <tr><th>ID</th><th>Dish Name</th><th>Category</th><th>Price</th><th>Calories</th><th>Stock</th><th>Action</th></tr>");
            out.println("        </thead>");
            out.println("        <tbody>");

            for (MenuItem item : items) {
                out.println("          <tr>");
                out.println("            <td>" + item.getItemId() + "</td>");
                out.println("            <td><strong>" + item.getItemName() + "</strong> " + (item.isHealthy() ? "<span class='tag'>Healthy</span>" : "") + "</td>");
                out.println("            <td>" + item.getCategory() + "</td>");
                out.println("            <td>" + item.getPrice() + " Cr</td>");
                out.println("            <td>" + (item.getCalories() != null ? item.getCalories() + " kcal" : "-") + "</td>");
                out.println("            <td>" + item.getAvailableQuantity() + " left</td>");
                out.println("            <td><form method='POST' action='/api/java/order' style='margin:0;'><input type='hidden' name='studentId' value='22'><input type='hidden' name='itemId' value='" + item.getItemId() + "'><button type='submit' class='btn'>Add & Order</button></form></td>");
                out.println("          </tr>");
            }

            out.println("        </tbody>");
            out.println("      </table>");
            out.println("    </div>");

            // Servlets API endpoints links
            out.println("    <div class='card'>");
            out.println("      <h2>🔌 Active Java Servlet Endpoints</h2>");
            out.println("      <ul>");
            out.println("        <li><a href='/api/java/menu' style='color:#38bdf8;' target='_blank'><code>GET /api/java/menu</code></a> — Handled by <code>MenuServlet</code></li>");
            out.println("        <li><a href='/api/java/kitchen' style='color:#38bdf8;' target='_blank'><code>GET /api/java/kitchen</code></a> — Handled by <code>KitchenQueueServlet</code></li>");
            out.println("        <li><a href='/api/java/history?studentId=22' style='color:#38bdf8;' target='_blank'><code>GET /api/java/history</code></a> — Handled by <code>OrderHistoryServlet</code></li>");
            out.println("        <li><a href='/api/java/history?studentId=22&format=csv' style='color:#38bdf8;' target='_blank'><code>GET /api/java/history?format=csv</code></a> — CSV Download Stream</li>");
            out.println("      </ul>");
            out.println("    </div>");

            out.println("  </div>");

            // Footer
            out.println("  <div class='footer'>");
            out.println("    SmartMess Java Web Application • Powered by Java Servlets &amp; PostgreSQL JDBC • Review 2");
            out.println("  </div>");

            out.println("</body>");
            out.println("</html>");
        }
    }
}
